453:   function resolveRoundScore() {
454:     const fight = state.fight;
455:     const playerHits = fight.playerScore || 0;
456:     const opponentHits = fight.opponentScore || 0;
457:     const playerWonRound = playerHits > opponentHits;
458:     const opponentWonRound = opponentHits > playerHits;
459: 
460:     fight.playerJudgeScore = (fight.playerJudgeScore || 0) + (playerWonRound ? 10 : 9);
461:     fight.opponentJudgeScore = (fight.opponentJudgeScore || 0) + (opponentWonRound ? 10 : 9);
462: 
463:     if (fight.round >= fight.totalRounds) {
464:       const playerTotal = fight.playerJudgeScore;
465:       const opponentTotal = fight.opponentJudgeScore;
466:       endFight(playerTotal === opponentTotal ? 'draw' : playerTotal > opponentTotal ? 'win' : 'loss');
467:       return;
468:     }
469: 
470:     const completedRound = fight.round;
471:     fight.round += 1;
472:     fight.timer = 180;
473:     fight.playerScore = 0;
474:     fight.opponentScore = 0;
475:     fight.playerHealth = clamp(fight.playerHealth + 12, 0, 100);
476:     fight.opponentHealth = clamp(fight.opponentHealth + 12, 0, 100);
477:     fight.playerStamina = 100;
478:     fight.opponentStamina = 100;
479:     battle.player.health = fight.playerHealth;
480:     battle.opponent.health = fight.opponentHealth;
