502:   function processPlayerMove(key) {
503:     const fight = state.fight;
504:     if (fight.phase !== 'live') return;
505: 
506:     if (key === 'guard') {
507:       battle.player.guard = true;
508:       fight.lastFeedback = 'Guardando. O adversário tenta quebrar a pressão.';
509:       return;
510:     }
511: 
512:     if (key === 'dodge') {
513:       battle.player.dodge = 0.6;
514:       fight.lastFeedback = 'Esquiva rápida. Corte o ângulo de ataque.';
515:       return;
516:     }
517: 
518:     if (key === 'clinch') {
519:       fight.lastFeedback = 'Clinche. Reduza a velocidade e recupere stamina.';
520:       return;
521:     }
522: 
523:     const punchTypes = ['jab', 'cross', 'hook', 'upper', 'body'];
524:     if (!punchTypes.includes(key)) return;
525: 
526:     const attackDamage = { jab: 7, cross: 10, hook: 13, upper: 11, body: 9 }[key];
527:     const dist = Math.abs(battle.player.x - battle.opponent.x);
528:     fight.totalShots = (fight.totalShots || 0) + 1;
529:     if (dist > 27) {
530:       fight.lastFeedback = 'Seu golpe foi longo. Feche a distância.';
531:       return;
532:     }
533: 
534:     const blocked = battle.opponent.guard && Math.random() < 0.5;
535:     const actualDamage = blocked ? Math.max(2, Math.round(attackDamage * 0.35)) : attackDamage + Math.round(Math.random() * 4);
536: 
537:     if (blocked) {
538:       fight.blocked = (fight.blocked || 0) + 1;
539:       fight.lastFeedback = 'Bloqueio importante. Mantenha a pressão.';
540:     } else {
541:       fight.landed = (fight.landed || 0) + 1;
542:       fight.playerScore = (fight.playerScore || 0) + 1;
543:       battle.opponent.health = Math.max(0, battle.opponent.health - actualDamage);
544:       state.fight.opponentHealth = battle.opponent.health;
545:       fight.lastFeedback = `${key.toUpperCase()} conectou! O rival sentiu o impacto.`;
546:     }
547: 
548:     if (battle.opponent.health <= 0) {
549:       endFight('win');
550:       return;
551:     }
552: 
553:     fight.accuracy = Math.round((fight.landed / Math.max(1, fight.totalShots)) * 100);
554:   }
555: 
556:   function aiAttack() {
557:     const fight = state.fight;
558:     if (fight.phase !== 'live' || battle.ended) return;
559:     const dist = Math.abs(battle.player.x - battle.opponent.x);
560:     const chance = Math.random();
561: 
562:     if (dist > 25) {
563:       battle.opponent.x += chance > 0.55 ? 1.2 : -0.8;
564:       battle.opponent.x = clamp(battle.opponent.x, 52, 90);
565:       fight.lastFeedback = 'O rival avança para fechar a distância.';
566:       return;
567:     }
568: 
569:     if (chance > 0.6) {
570:       battle.opponent.guard = true;
571:       fight.lastFeedback = 'O adversário se protege. Aproveite a brecha.';
572:       return;
573:     }
574: 
575:     const selected = ['jab', 'cross', 'hook'][Math.floor(Math.random() * 3)];
576:     const damage = { jab: 5, cross: 8, hook: 12 }[selected];
577:     const isBlocked = battle.player.guard && Math.random() > 0.4;
578:     const finalDamage = isBlocked ? Math.max(2, Math.round(damage * 0.4)) : damage + Math.round(Math.random() * 4);
579: 
580:     if (isBlocked) {
581:       fight.blocked = (fight.blocked || 0) + 1;
582:       fight.lastFeedback = 'Você absorveu o golpe e manteve a guarda.';
583:     } else {
584:       battle.player.health = Math.max(0, battle.player.health - finalDamage);
585:       state.fight.playerHealth = battle.player.health;
586:       fight.lastFeedback = `Contra-ataque do rival: ${selected.toUpperCase()} conectou.`;
587:       if (battle.player.health <= 0) {
588:         endFight('loss');
589:         return;
590:       }
591:     }
592: 
593:     battle.opponent.guard = false;
594:     battle.opponent.stamina = clamp(battle.opponent.stamina - 5, 0, 100);
595:     state.fight.opponentStamina = battle.opponent.stamina;
596:   }
597: 
598:   function updateMovement(dt) {
599:     const moveVector = { x: 0, y: 0 };
600:     if (keyboard.w || keyboard.ArrowUp) moveVector.y -= 1;
601:     if (keyboard.s || keyboard.ArrowDown) moveVector.y += 1;
602:     if (keyboard.a || keyboard.ArrowLeft) moveVector.x -= 1;
603:     if (keyboard.d || keyboard.ArrowRight) moveVector.x += 1;
604: 
605:     if (moveVector.x !== 0 || moveVector.y !== 0) {
606:       const speed = 12 * dt;
607:       battle.player.x += moveVector.x * speed;
608:       battle.player.x = clamp(battle.player.x, 12, 48);
609:       battle.player.y += moveVector.y * speed;
610:       battle.player.y = clamp(battle.player.y, -28, 28);
611:       state.fight.playerPosition = battle.player.x;
612:     }
613: 
614:     if (!battle.started) return;
615:     const dist = Math.abs(battle.player.x - battle.opponent.x);
616:     if (dist > 16) {
617:       battle.opponent.x += battle.opponent.x > battle.player.x ? -0.35 : 0.35;
618:       battle.opponent.x = clamp(battle.opponent.x, 52, 88);
619:     }
620: 
621:     battle.opponent.guard = false;
622:     if (battle.player.guard) {
623:       battle.player.guard = state.fight.timer % 1.5 < 0.5;
624:     }
625: 
626:     state.fight.playerStamina = clamp(battle.player.stamina - (keyboard.a || keyboard.d ? 0.18 : 0.05), 0, 100);
627:     battle.player.stamina = state.fight.playerStamina;
628:     state.fight.opponentStamina = clamp(battle.opponent.stamina - 0.15, 0, 100);
629:     battle.opponent.stamina = state.fight.opponentStamina;
630:   }
631: 
632:   function updateFight(dt) {
633:     const fight = state.fight;
634:     if (fight.phase !== 'live' || battle.ended) return;
635:     fight.timer = clamp((fight.timer || 180) - dt, 0, 180);
636: 
637:     if (fight.timer <= 0) {
638:       if (fight.round >= fight.totalRounds) {
639:         const playerScore = fight.playerScore || 0;
640:         const opponentScore = fight.opponentScore || 0;
641:         endFight(playerScore === opponentScore ? 'draw' : playerScore > opponentScore ? 'win' : 'loss');
642:         return;
643:       }
644:       fight.round += 1;
645:       fight.timer = 180;
646:       fight.lastFeedback = `Round ${fight.round} começou. Mude a postura e mantenha o ritmo.`;
647:       fight.playerScore = 0;
648:       fight.opponentScore = 0;
649:       battle.player.health = clamp(battle.player.health + 12, 0, 100);
650:       battle.opponent.health = clamp(battle.opponent.health + 12, 0, 100);
651:       state.fight.playerHealth = battle.player.health;
652:       state.fight.opponentHealth = battle.opponent.health;
653:     }
654: 
655:     if (performance.now() - battle.lastAiDecision > 1200) {
656:       battle.lastAiDecision = performance.now();
657:       aiAttack();
658:     }
659: 
660:     updateMovement(dt);
661: 
662:     if (!battle.ended) {
663:       state.fight.playerHealth = battle.player.health;
664:       state.fight.opponentHealth = battle.opponent.health;
665:       state.fight.playerStamina = battle.player.stamina;
666:       state.fight.opponentStamina = battle.opponent.stamina;
667:     }
668: 
669:     updateFightHud();
670:   }
