672:   function renderArena() {
673:     const canvas = refs.arena;
674:     if (!canvas) return;
675:     const ctx = canvas.getContext('2d');
676:     const ratio = window.devicePixelRatio || 1;
677:     const rect = canvas.getBoundingClientRect();
678:     const width = rect.width || 900;
679:     const height = rect.height || 420;
680: 
681:     canvas.width = width * ratio;
682:     canvas.height = height * ratio;
683:     ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
684: 
685:     const ringLeft = 24;
686:     const ringTop = 20;
687:     const ringWidth = width - 48;
688:     const ringHeight = height - 55;
689: 
690:     ctx.clearRect(0, 0, width, height);
691:     const sky = ctx.createLinearGradient(0, 0, 0, height);
692:     sky.addColorStop(0, '#0b1210');
693:     sky.addColorStop(1, '#1c2a25');
694:     ctx.fillStyle = sky;
695:     ctx.fillRect(0, 0, width, height);
696: 
697:     ctx.fillStyle = '#0c3b2e';
698:     ctx.fillRect(ringLeft, ringTop, ringWidth, ringHeight);
699:     ctx.strokeStyle = '#d2b46d';
700:     ctx.lineWidth = 2;
701:     ctx.strokeRect(ringLeft + 6, ringTop + 6, ringWidth - 12, ringHeight - 12);
702:     ctx.strokeStyle = 'rgba(255,255,255,0.2)';
703:     ctx.beginPath();
704:     ctx.moveTo(ringLeft + 10, ringTop + 40);
705:     ctx.lineTo(width - ringLeft - 10, ringTop + 40);
706:     ctx.moveTo(ringLeft + 10, ringTop + ringHeight - 40);
707:     ctx.lineTo(width - ringLeft - 10, ringTop + ringHeight - 40);
708:     ctx.stroke();
709: 
710:     const playerX = ringLeft + (battle.player.x / 100) * (ringWidth - 25);
711:     const playerY = ringTop + ringHeight * 0.73 + battle.player.y;
712:     const enemyX = ringLeft + (battle.opponent.x / 100) * (ringWidth - 25);
713:     const enemyY = ringTop + ringHeight * 0.73 + battle.opponent.y;
714: 
715:     drawFighter(ctx, playerX, playerY, state.player.color || '#d64f3e', battle.player.guard, false);
716:     drawFighter(ctx, enemyX, enemyY, '#5a8791', battle.opponent.guard, true);
717: 
718:     ctx.fillStyle = 'rgba(0,0,0,0.25)';
719:     ctx.fillRect(ringLeft + 8, ringTop + 8, ringWidth - 16, 12);
720:     ctx.fillRect(ringLeft + 8, ringTop + ringHeight - 20, ringWidth - 16, 12);
721:   }
