723:   function drawFighter(ctx, x, y, color, guard, enemy) {
724:     const bodyColor = color;
725:     ctx.save();
726:     ctx.translate(x, y);
727:     ctx.fillStyle = '#f0d0a6';
728:     ctx.beginPath();
729:     ctx.arc(0, -52, 15, 0, Math.PI * 2);
730:     ctx.fill();
731: 
732:     ctx.fillStyle = bodyColor;
733:     ctx.fillRect(-14, -34, 28, 45);
734: 
735:     ctx.strokeStyle = '#d9c68d';
736:     ctx.lineWidth = 4;
737:     ctx.beginPath();
738:     ctx.moveTo(-12, -18);
739:     ctx.lineTo(-28, 24);
740:     ctx.moveTo(12, -18);
741:     ctx.lineTo(26, 24);
742:     ctx.moveTo(-6, 12);
743:     ctx.lineTo(-18, 54);
744:     ctx.moveTo(6, 12);
745:     ctx.lineTo(16, 54);
746:     ctx.stroke();
747: 
748:     if (guard) {
749:       ctx.strokeStyle = '#eaecb8';
750:       ctx.lineWidth = 3;
751:       ctx.beginPath();
752:       ctx.moveTo(-20, -12);
753:       ctx.lineTo(-38, 6);
754:       ctx.moveTo(20, -12);
755:       ctx.lineTo(38, 6);
756:       ctx.stroke();
757:     }
758: 
759:     if (enemy) {
760:       ctx.fillStyle = 'rgba(255,255,255,0.08)';
761:       ctx.fillRect(-30, -90, 60, 12);
762:     }
763:     ctx.restore();
764:   }
